import re

def count_characters(input_string):
    return len(input_string)

def count_tokens(input_string):
    return len(re.split(r'\W+', input_string))

def count_words(input_string):
    return len(re.split(r'\s+', input_string))

def check_access(input_string):
    if count_tokens(input_string) > 1:
        return "Access denied."
    elif re.search(r'opening defence', input_string):
        return "Access denied."
    else:
        return ""

def main():
    input_string = input("Enter a string: ")
    character_count = count_characters(input_string)
    token_count = count_tokens(input_string)
    word_count = count_words(input_string)
    access_result = check_access(input_string)
    print(f"Character count: {character_count}")
    print(f"Token count: {token_count}")
    print(f"Word count: {word_count}")
    print(access_result)

